/* ---------------------------------------------------------------
   GALLERY ADMIN LAYER
   A GALLERY is one group of cases (normally one per procedure, e.g.
   "Facelift"). Admin ("Gallery") can: add a gallery, rename it, change
   its category, hide or delete it, switch its 18+ confirmation, and
   add / edit / reorder / hide / delete the cases inside it.
   In this preview the choices are kept in this browser
   (localStorage "nps.gallery2"); in the real Admin, Publish saves them
   for every visitor.
     state = { cases:{id:{field:value}}, added:[case], galleries:{id:{name,cat,ageGate,hidden,deleted,created}},
               custom:[{id,name,cat}] }
   --------------------------------------------------------------- */
(function () {
  var NPS = window.NPS, L = NPS.library, KEY = 'nps.gallery2';
  var short = function (t) { return t.replace(/\s*\(.*\)/, ''); };
  L.fields = ['title', 'addOn', 'patient', 'age', 'height', 'weight', 'postop', 'implant'];
  L.base = JSON.parse(JSON.stringify(L.cases));            // the imported cases, untouched
  L.categories = ['Face', 'Breast', 'Body', 'Skin & aesthetics'];
  L.load = function () {
    var o = {}; try { o = JSON.parse(localStorage.getItem(KEY) || '{}') || {}; } catch (e) {}
    o.cases = o.cases || {}; o.added = o.added || []; o.galleries = o.galleries || {}; o.custom = o.custom || []; return o;
  };
  L.save = function (st) { localStorage.setItem(KEY, JSON.stringify(st)); };

  /* galleries from a state + case list */
  L.defs = function (st, cases) {
    var map = {}, ids = [], procs = {}; NPS.procedures.forEach(function (p) { procs[p.id] = p; });
    function add(id) {
      if (!id || map[id]) return;
      var p = procs[id], cu = st.custom.filter(function (x) { return x.id === id; })[0], o = st.galleries[id] || {};
      map[id] = { id: id, name: o.name != null ? o.name : (cu ? cu.name : (p ? short(p.title) : id)), cat: o.cat || (cu ? cu.cat : (p ? p.cat : 'Face')),
        procedure: p ? p.id : null, custom: !!cu, ageGate: o.ageGate != null ? !!o.ageGate : L.ageGate.procedures.indexOf(id) > -1, hidden: !!o.hidden, deleted: !!o.deleted };
      ids.push(id);
    }
    cases.forEach(function (c) { add(c.primary); });
    st.custom.forEach(function (x) { add(x.id); });
    Object.keys(st.galleries).forEach(function (id) { if (st.galleries[id].created) add(id); });
    return { ids: ids, map: map };
  };
  /* the cases as the public sees them: overrides applied, added cases included */
  L.merge = function (st) {
    var out = JSON.parse(JSON.stringify(L.base));
    out.forEach(function (c) {
      var o = st.cases[c.id]; if (!o) return;
      Object.keys(o).forEach(function (k) { if (k === 'show') c.show = Object.assign({}, c.show, o.show); else if (o[k] === '' || o[k] == null) delete c[k]; else c[k] = o[k]; });
    });
    return out.concat(JSON.parse(JSON.stringify(st.added)));
  };
  L.gated = function (c, defs) {
    return [c.primary].concat(c.procedures || []).some(function (id) { var g = defs.map[id]; return g ? g.ageGate : L.ageGate.procedures.indexOf(id) > -1; });
  };

  /* what the public site uses */
  L.state = L.load();
  L.cases = L.merge(L.state);
  L.state.added.forEach(function (c) { c.views.forEach(function (v) { ['before', 'after'].forEach(function (k) { var p = v[k]; if (p.src) NPS.images[p.image] = { src: p.src, w: p.w, h: p.h, alt: p.alt || '' }; }); }); });
  L.galleries = function () {
    var d = L.defs(L.state, L.cases);
    return d.ids.map(function (id) { var g = d.map[id]; g.count = L.cases.filter(function (c) { return c.primary === id && c.visible !== false; }).length; return g; });
  };
  L.gallery = function (id) { return L.defs(L.state, L.cases).map[id]; };
  L.isGated = function (c) { return L.gated(c, L.defs(L.state, L.cases)); };
  L.publicCases = function () {
    var d = L.defs(L.state, L.cases);
    return L.cases.filter(function (c) { var g = d.map[c.primary]; return c.visible !== false && !c.deleted && !(g && (g.hidden || g.deleted)); }).sort(function (a, b) { return (a.order || 0) - (b.order || 0); });
  };
})();
